// Name:   Function CoreUObject.FRotator.Clamp
// Params:
//   ReturnValue                  0x000(0x000), 
FRotator FRotator::Clamp() const
{
    FRotator r = { Pitch, Yaw, Roll };
    if (r.Yaw > 180.0)
        r.Yaw -= 360.0;
    else if (r.Yaw < -180.0)
        r.Yaw += 360.0;
    if (r.Pitch > 180.0)
        r.Pitch -= 360.0;
    else if (r.Pitch < -180.0)
        r.Pitch += 360.0;
    if (r.Pitch < -89.0)
        r.Pitch = -89.0;
    else if (r.Pitch > 89.0)
        r.Pitch = 89.0;
    r.Roll = 0.0;
    return r;
}























