// Name:   Function CoreUObject.FVector.Normalize360
// Params:
//   angle                        0x000(0x000), 
void FVector::Normalize360(FVector& angle)
{
    const double maxX1 = 80.0;

    while (angle.X > maxX1)
        angle.X -= 180.0;
    while (angle.X < -maxX1)
        angle.X += 180.0;
    while (angle.Y > 180.0)
        angle.Y -= 360.0;
    while (angle.Y < -180.0)
        angle.Y += 360.0;
}

// Name:   Function CoreUObject.FVector.Dot
// Params:
//   ReturnValue                  0x000(0x000), 
//   b                            0x000(0x000), 
double FVector::Dot(const FVector& b) const
{
    return (X * b.X) + (Y * b.Y) + (Z * b.Z);
}

// Name:   Function CoreUObject.FVector.MagnitudeSqr
// Params:
//   ReturnValue                  0x000(0x000), 
double FVector::MagnitudeSqr() const
{
    return Dot(*this);
}

// Name:   Function CoreUObject.FVector.Magnitude
// Params:
//   ReturnValue                  0x000(0x000), 
double FVector::Magnitude() const
{
    return sqrt(MagnitudeSqr());
}

// Name:   Function CoreUObject.FVector.Unit
// Params:
//   ReturnValue                  0x000(0x000), 
FVector FVector::Unit() const
{
    const double fMagnitude = Magnitude();
    return FVector(X / fMagnitude, Y / fMagnitude, Z / fMagnitude);
}

// Name:   Function CoreUObject.FVector.ToRotator
// Params:
//   ReturnValue                  0x000(0x000), 
FRotator FVector::ToRotator() const
{
    static constexpr double PI = 3.14159265359;
    // Pitch, Yaw, Roll
    return FRotator(asin(Z / Magnitude()) * 180.0 / PI, atan2(Y, X) * 180.0 / PI, 0.0);
}

// Name:   Function CoreUObject.FVector.Distance
// Params:
//   ReturnValue                  0x000(0x000), 
//   v                            0x000(0x000), 
double FVector::Distance(const FVector& v) const
{
    return sqrt(pow(v.X - X, 2) + pow(v.Y - Y, 2) + pow(v.Z - Z, 2));
}

// Name:   Function CoreUObject.FVector.DistanceMeter
// Params:
//   ReturnValue                  0x000(0x000), 
//   v                            0x000(0x000), 
double FVector::DistanceMeter(FVector& v) const
{
    return Distance(v) * 0.01;
}
















































