// Name:   Function CoreUObject.UObject.GetFullName
// Params:
//   ReturnValue                  0x000(0x000), 
std::string UObject::GetFullName() const
{
    std::string name;
    if (Class != nullptr)
    {
        std::string temp;
        for (auto p = Outer; p; p = p->Outer)
        {
            temp = p->GetName() + "." + temp;
        }
        name = Class->GetName();
        name += " ";
        name += temp;
        name += GetName();
    }
    return name;
}

